-- LuaLS stubs for HyprLUI's Lua API (hl.plugin.hyprlui.*).
--
-- Hand-maintained, not autogenerated: Hyprland's own stub generator
-- (meta/generateLuaStubs.py in the Hyprland repo) only understands its own
-- internal hl.* binding registration pattern, and deliberately types
-- hl.plugin.<name> as `any` since it has no visibility into what a plugin
-- registers at runtime via HyprlandAPI::addLuaFunction. Keep this in sync
-- by hand with src/ui/LuaBridge.cpp/.hpp whenever the API changes.
---@meta

---@alias HyprLUI.Color integer|{r?: number, g?: number, b?: number, a?: number}
---@alias HyprLUI.Align "start"|"center"|"end"
---@alias HyprLUI.ZOrder "overlay"|"background"
---@alias HyprLUI.Anchor "top-left"|"top"|"top-right"|"left"|"center"|"right"|"bottom-left"|"bottom"|"bottom-right"
-- Same selector syntax as Hyprland's own window/layer rule `mon:` fields: a
-- direction char, "+N"/"-N", a numeric id, or a static selector/output
-- name - resolved relative to whichever monitor is focused right now,
-- ONCE, at window-creation time. No "current"/"focused" keyword on
-- purpose (it would shadow a monitor actually named "current" in the
-- user's own config) - omit `monitor` entirely for "the focused monitor",
-- and a selector that matches nothing also falls back to focused rather
-- than erroring.
---@alias HyprLUI.MonitorSelector string

-- Requires `anchor` (a reserved zone needs a resolved target monitor),
-- and must be an edge the anchor actually touches - anchor="top" only
-- accepts "top"; a corner anchor like "top-left" accepts "top" or
-- "left"; "center" accepts neither. Errors otherwise. Reserves screen-
-- edge space equal to the window's own current size along the
-- perpendicular axis (top/bottom -> height, left/right -> width) - see
-- LuaBridge.hpp for composition/limitation details.
---@alias HyprLUI.Edge "top"|"right"|"bottom"|"left"

-- The marker table hyprlui.Bind(name) returns - ties a widget property to
-- watcher `name`'s current value. Opaque; just pass it straight through
-- as a field's value (e.g. Text{ text = Bind("volume") }).
---@class HyprLUI.BindMarker
---@field __bind string

---@class HyprLUI.WatchOptions
---@field interval? number

---@alias HyprLUI.WatcherFn fun(): any
---@alias HyprLUI.WatchFn fun(name: string, fn: HyprLUI.WatcherFn, opts?: HyprLUI.WatchOptions): nil

-- The only supported types for hyprlui.persistent() - no tables, no
-- functions (see LuaBridge.hpp for why: a real native re-encoding, not
-- just a kept Lua reference, since the whole Lua interpreter is torn
-- down and recreated on every config reload).
---@alias HyprLUI.PersistentValue number|string|boolean

-- Returned by hyprlui.persistent(key, default) - :get() always reads the
-- CURRENT value (never a stale snapshot from when persistent() was
-- called); :set(value) overwrites it. Deliberately explicit methods, not
-- a mutable field - see LuaBridge.hpp. Generic over `T` (see
-- hl.plugin.hyprlui.persistent()'s own declaration further down, which is
-- what actually pins T to whatever `default`'s type was at a given call
-- site) so `local vol = persistent("volume", 50); vol:get()` resolves to
-- `number`, not the broad HyprLUI.PersistentValue union every call site
-- would otherwise share. :set() is typed to that same T, matching the
-- overwhelmingly common case (reading/writing the same type back) - the
-- underlying store doesn't actually enforce this at runtime (see
-- CPersistenceStore's permissive type-mismatch handling), so a genuine
-- type change is still possible, just not statically typed for.
---@class HyprLUI.PersistentStore<T>
---@field get fun(self: HyprLUI.PersistentStore<T>): T
---@field set fun(self: HyprLUI.PersistentStore<T>, value: T): nil

-- Phase 12 (DESIGN.md) native-services types. run_cmd()'s callback always
-- gets a string (empty on a spawn/pipe failure - see LuaBridge.hpp for
-- why this can't distinguish "" from a genuine failure any other way,
-- given no exit code is available). open_socket()'s callback gets `nil`
-- on a connect failure instead - unlike run_cmd, "did this even connect"
-- is a load-bearing distinction a caller must be able to check.
---@alias HyprLUI.RunCmdCallback fun(output: string): nil
---@alias HyprLUI.SocketReadCallback fun(data: string?): nil
---@alias HyprLUI.OpenSocketCallback fun(sock: HyprLUI.Socket?): nil

-- Returned by hyprlui.open_socket()'s callback on a successful connect.
-- :read()'s callback fires with exactly one read() call's worth of data
-- (never internally drained/batched across multiple reads), or `nil` once
-- the peer closes the connection (after which the socket is closed and
-- unusable - a stray :read() on it after that point still fires its
-- callback with `nil` rather than erroring). Only one pending :read() at
-- a time - a second call before the first resolves replaces it.
---@class HyprLUI.Socket
---@field read fun(self: HyprLUI.Socket, callback: HyprLUI.SocketReadCallback): nil
---@field write fun(self: HyprLUI.Socket, data: string): nil
---@field close fun(self: HyprLUI.Socket): nil

-- hyprlui.animation({leaf="in"|"out", ...}) (Phase 13, DESIGN.md) -
-- configures the shared fade duration/curve for set_widget_visible()
-- transitions. NOT the same tree as Hyprland's own hl.animation() -
-- verified there's no public API to register a new leaf into that tree
-- from outside, so this is a small separate config surface, shaped like
-- hl.animation()'s own table call for familiarity. `speed` is in
-- deciseconds (tenths of a second), same unit hl.animation() uses.
-- `enabled` defaults to true; pass enabled=false to turn an already-
-- configured leaf back into an instant (non-animated) toggle - speed/
-- bezier are irrelevant and may be omitted in that case.
---@class HyprLUI.AnimationOpts
---@field leaf "in"|"out"
---@field enabled? boolean
---@field speed? number
---@field bezier? string

-- A widget's own `animationIn`/`animationOut` field (Phase 13 follow-up) -
-- same shape as HyprLUI.AnimationOpts minus `leaf` (implied by which
-- field this is), overriding hyprlui.animation()'s global config for just
-- this ONE widget. Self-contained, not a partial merge with the global
-- config - `speed`/`bezier` are only required unless this explicitly sets
-- `enabled = false` (which forces this widget's toggle to stay instant
-- even if the global leaf is enabled).
---@class HyprLUI.AnimationOverride
---@field enabled? boolean
---@field speed? number
---@field bezier? string

-- Either a single number (applied to all four sides) or a table with any
-- subset of sides given (an omitted side defaults to 0, NOT to whatever
-- the uniform-number form would have used) - same convention `color`
-- already uses for its two accepted shapes.
---@alias HyprLUI.EdgeInsets number|{top?: number, right?: number, bottom?: number, left?: number}

-- Fields shared by every widget constructor table (Phase 7, DESIGN.md).
-- `x`/`y` are honored by Stack children (absolute positioning) and ignored
-- by Row/Column children (arrange() overwrites them). Numeric entries
-- ([1], [2], ...) are child widgets - see HyprLUI.WidgetSpec below.
--
-- `padding` insets a CONTAINER's own children from its edges - only Row/
-- Column and Input's auto-owned label currently interpret it; Stack's
-- manual/absolute positioning leaves it unused by design. `margin` is a
-- widget's own requested space around ITSELF, read by whichever container
-- lays it out - only Row/Column currently read a child's margin (added on
-- top of `gap`, CSS-flexbox-item style), Stack again leaves it unused.
--
-- `minW`/`minH`/`maxW`/`maxH` clamp the measured size on each axis
-- independently (either bound may be omitted) - applied after any fixed
-- w/h override, same precedence CSS gives min/max-width. A `Text` whose
-- content doesn't fit `maxW` truncates with an ellipsis (Hyprland's own
-- Pango-based text renderer already does this given a max width - the
-- chosen v1 overflow default, see DESIGN.md Phase 7); `minW`/`minH` widen
-- the layout box without stretching a Text's rendered glyphs.
--
-- `opacity` (0-1, default 1) multiplies with every ancestor's own opacity
-- - a semi-transparent container fades its children too, not just itself.
--
-- `zIndex` (default 0) reorders paint order among a widget's OWN siblings
-- only (higher paints later/on top) - not a full CSS stacking-context
-- system, just a sibling-local override of plain insertion order.
--
-- `debug`/`debugCascade`/`debugShow` - box-model debug overlay (outlines +
-- small labels for padding/margin/id/size/opacity-zIndex, plus a fill over
-- interactive widgets' hit-target area), drawn on top of everything else,
-- unaffected by the widget's own opacity/zIndex. `debug` is tri-state:
-- omitted means "inherit whatever the nearest ancestor resolved to" (the
-- window root inherits `false`), `true`/`false` is an explicit override
-- that itself cascades to descendants the same way. `debugCascade`
-- (default true) walls a subtree off from that inheritance entirely when
-- `false` - neither this widget's own `debug` value nor anything above it
-- reaches its children, who start fresh. `debugShow` force-overrides
-- individual detail categories on/off; any category left out stays "auto"
-- (shown only once the widget is big enough to render it legibly, and -
-- for `zOpacity` only - only when opacity/zIndex are actually non-default)
-- unless some ancestor already forced it via inheritance.
---@class HyprLUI.WidgetCommon
---@field id? string
---@field x? number
---@field y? number
---@field visible? boolean
---@field padding? HyprLUI.EdgeInsets
---@field margin? HyprLUI.EdgeInsets
---@field minW? number
---@field minH? number
---@field maxW? number
---@field maxH? number
---@field opacity? number
---@field zIndex? integer
---@field debug? boolean
---@field debugCascade? boolean
---@field debugShow? HyprLUI.DebugShow
---@field debugFontSize? integer
---@field disabled? boolean
---@field hoverColor? HyprLUI.Color
---@field disabledColor? HyprLUI.Color
---@field onHoverStart? HyprLUI.OnHoverFn
---@field onHoverEnd? HyprLUI.OnHoverFn
---@field onScroll? HyprLUI.OnScrollFn
---@field onClick? HyprLUI.OnClickFn
---@field animationIn? HyprLUI.AnimationOverride
---@field animationOut? HyprLUI.AnimationOverride
---@field [integer] HyprLUI.WidgetSpec

-- `delta` is the raw IPointer::SAxisEvent value forwarded as-is (no
-- normalization); `vertical` is true for the common mouse-wheel axis,
-- false for horizontal scroll.
---@alias HyprLUI.OnScrollFn fun(delta: number, vertical: boolean)

---@class HyprLUI.DebugShow
---@field box? boolean
---@field padding? boolean
---@field margin? boolean
---@field id? boolean
---@field size? boolean
---@field zOpacity? boolean
---@field hitTarget? boolean

---@class HyprLUI.BoxSpec : HyprLUI.WidgetCommon
---@field w number
---@field h number
---@field color? HyprLUI.Color
---@field rounding? integer

---@class HyprLUI.TextSpec : HyprLUI.WidgetCommon
---@field text string|HyprLUI.BindMarker
---@field size? integer
---@field color? HyprLUI.Color
---@field font? string

-- Manual/absolute positioning - the escape hatch. Size-to-content is the
-- bounding box of its children unless w/h are given.
---@class HyprLUI.StackSpec : HyprLUI.WidgetCommon
---@field w? number
---@field h? number

-- Flexbox-lite: packs children along the row/column axis. `padding` (from
-- WidgetCommon) insets from the container's own edges; a child's own
-- `margin` (also WidgetCommon) adds extra space around itself on top of
-- `gap`. No wrap, no justify/space-between (v1 scope - see DESIGN.md).
---@class HyprLUI.FlexSpec : HyprLUI.WidgetCommon
---@field w? number
---@field h? number
---@field gap? number
---@field align? HyprLUI.Align

---@alias HyprLUI.OnClickFn fun()
---@alias HyprLUI.OnFocusFn fun()
---@alias HyprLUI.OnBlurFn fun()
---@alias HyprLUI.OnHoverFn fun()
-- `keysym` is an xkb_keysym_t (already layout/shift-aware - see
-- LuaBridge.hpp) - compare against xkbcommon's XKB_KEY_* integer values.
-- `pressed` is true on key-down, false on key-up.
---@alias HyprLUI.OnKeyFn fun(keysym: integer, pressed: boolean)
-- Fires with an Input's new text after it changes from typing/Backspace -
-- not from a programmatic set_input_text() call.
---@alias HyprLUI.OnChangeFn fun(text: string)

-- Like Box, but always a real click target structurally, even with no
-- onClick set (`onClick` itself is a WidgetCommon field now, not
-- Button-specific - see LuaBridge.hpp for press/release/pass-through
-- semantics). Children are positioned manually/absolutely inside it,
-- same as Stack.
---@class HyprLUI.ButtonSpec : HyprLUI.WidgetCommon
---@field w number
---@field h number
---@field color? HyprLUI.Color
---@field rounding? integer

-- A focusable rectangle that behaves like an actual text field by default
-- - typing appends a character, Backspace removes the last one, current
-- text renders automatically (see LuaBridge.hpp) - printable-ASCII only,
-- no cursor/selection/IME/non-ASCII/clipboard; layer that on top of onKey
-- if needed, which keeps firing for every key regardless. Gains HyprLUI's
-- single global keyboard-focus slot by being clicked (grabbed on press)
-- or via focus_widget(); loses it by clicking elsewhere, or blur_widget().
-- A key that currently triggers a real Hyprland keybind never reaches a
-- focused Input at all (not just "not swallowed" - never forwarded to
-- onKey or the built-in capture either), so the user's keybinds behave
-- exactly as if HyprLUI didn't exist - this is absolute, no widget-level
-- opt-out. Everything else is swallowed while focused, so typing stays
-- local instead of leaking to whatever real window has actual keyboard
-- focus behind it.
---@class HyprLUI.InputSpec : HyprLUI.WidgetCommon
---@field w number
---@field h number
---@field color? HyprLUI.Color
---@field rounding? integer
---@field text? string
---@field textColor? HyprLUI.Color
---@field textSize? integer
---@field textFont? string
---@field onChange? HyprLUI.OnChangeFn
---@field onKey? HyprLUI.OnKeyFn
---@field onFocus? HyprLUI.OnFocusFn
---@field onBlur? HyprLUI.OnBlurFn

-- Decodes `path` (PNG/JPG/WEBP/SVG/AVIF/JXL) and draws it. Size-to-content
-- (the image's own natural pixel size) unless w/h are given, in which case
-- it's scaled/stretched to fill that box (unlike Text, which never
-- stretches its own glyphs). Synchronous - a bad path logs a warning and
-- leaves it drawing nothing rather than erroring the whole window{} out.
---@class HyprLUI.ImageSpec : HyprLUI.WidgetCommon
---@field w? number
---@field h? number
---@field path string
---@field rounding? integer

-- A thin separator line - pure Lua-side sugar over a Box with a computed
-- w/h. `length` is the dimension along the divider's own axis (w if
-- horizontal, the default, or h if vertical); `thickness` is the
-- perpendicular one.
---@class HyprLUI.DividerSpec : HyprLUI.WidgetCommon
---@field length number
---@field thickness? number
---@field orientation? "horizontal"|"vertical"
---@field color? HyprLUI.Color

-- Fires with a Checkbox's NEW checked state after a real click toggles it
-- (not from a programmatic set_checkbox_checked() call).
---@alias HyprLUI.OnChangeBoolFn fun(checked: boolean)

-- Checked/unchecked only (v1 scope) - not an animated toggle switch. Draws
-- like Box (`color`); when checked, an inset filled square using
-- `checkedColor` on top (a plain rect indicator, not a checkmark glyph).
-- Same click semantics/lifetime as Button - the difference is a Checkbox
-- owns its own boolean state, toggled by a real click before onChange
-- fires with the new value. `checked` seeds the initial state without
-- invoking onChange.
---@class HyprLUI.CheckboxSpec : HyprLUI.WidgetCommon
---@field w number
---@field h number
---@field color? HyprLUI.Color
---@field checkedColor? HyprLUI.Color
---@field rounding? integer
---@field checked? boolean
---@field onChange? HyprLUI.OnChangeBoolFn

---@alias HyprLUI.WidgetSpec HyprLUI.BoxSpec|HyprLUI.TextSpec|HyprLUI.StackSpec|HyprLUI.FlexSpec|HyprLUI.ButtonSpec|HyprLUI.InputSpec|HyprLUI.ImageSpec|HyprLUI.DividerSpec|HyprLUI.CheckboxSpec

-- Either `{ required = true }` (must be given at every Component() call)
-- or `{ default = value }` (falls back to `value`, any Lua type, if
-- omitted) - never both.
---@class HyprLUI.PropSpec
---@field required? boolean
---@field default? any

-- Registered via hyprlui.defineComponent(name, def) - see LuaBridge.hpp
-- for the full composability model (id-rewriting per instance, opts
-- overlay, scoping/upvalue rules). `render` returns exactly one widget
-- (the direct result of a single widget-constructor call).
---@class HyprLUI.ComponentDef
---@field props? table<string, HyprLUI.PropSpec>
---@field render fun(props: table): HyprLUI.WidgetSpec

-- Third argument to hyprlui.Component() - the same base widget fields
-- every other widget accepts at its own call site (x/y/padding/opacity/
-- etc., inherited from WidgetCommon), plus `key`: the instance key
-- (unprefixed root id; every descendant's explicit id becomes
-- `key .. "::" .. originalId`). Auto-generated if omitted.
---@class HyprLUI.ComponentOpts : HyprLUI.WidgetCommon
---@field key? string

-- Top-level table passed to hyprlui.window{} - the [1] entry is the root
-- widget (exactly one required: Stack/Row/Column/Text/Box).
--
-- Without `anchor`: x/y are a raw global (compositor-space) position.
-- With `anchor`: x/y are reinterpreted as an offset from that point on
-- the target monitor's usable box (positive always pushes inward).
---@class HyprLUI.WindowSpec
---@field name string
---@field x? number
---@field y? number
---@field w? number
---@field h? number
---@field zorder? HyprLUI.ZOrder
---@field anchor? HyprLUI.Anchor
---@field monitor? HyprLUI.MonitorSelector
---@field exclusive? HyprLUI.Edge
---@field [1] HyprLUI.WidgetSpec

